'use strict';
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const thermal=['#5756ad','#4e91c4','#62bba8','#e6d17c','#e48357','#b74056'],blue=['#d4e8ed','#91c9d6','#4199b5','#276895','#363c83'],windColours=['#cbe2ce','#93cbb3','#49a6a9','#427d9b','#6563a4','#91466f'];
const weatherCategories=[['No significant weather','#d7ba67'],['Recent weather','#b1aaa0'],['Fog / mist','#a2a9b4'],['Rain / drizzle','#388aae'],['Showers','#317289'],['Snow / ice','#9280b9'],['Storm / hail','#8b4168'],['Precipitation','#6c97b9'],['Other weather','#78868d'],['Thunderstorm nearby','#8b4168']];
const V={
 temperature:{label:'Air temperature',unit:'°C',min:-10,max:30,dec:1,colours:thermal,note:'Reported air temperature at the station.'},
 sea_temperature:{label:'Sea-surface temperature',unit:'°C',min:0,max:25,dec:1,colours:thermal,note:'Reported sea-surface temperature from marine observations.'},
 dewpoint:{label:'Dew point',unit:'°C',min:-10,max:25,dec:1,colours:thermal,note:'Reported dew-point temperature.'},
 humidity:{label:'Relative humidity',unit:'%',min:0,max:100,dec:0,colours:blue,note:'Usually derived from reported temperature and dew point. Check station details.'},
 wind:{label:'Mean wind speed',unit:'mph',min:0,max:50,dec:1,colours:windColours,note:'Reported mean wind, converted to mph. Different report networks may use different averaging periods.'},
 direction:{label:'Wind direction',unit:'°',dec:0,note:'Arrows point where the wind blows. Values and station details give the direction it comes from. ○ Calm · ↔ Variable.'},
 gust:{label:'Wind gusts',unit:'mph',min:0,max:70,dec:1,colours:windColours,note:'SYNOP: preceding 10-minute gust. METAR: reported gust. Missing gusts are not zero.'},
 pressure_msl:{label:'Sea-level pressure',unit:'hPa',min:970,max:1040,dec:1,colours:['#625a9c','#699fc0','#a3c9bc','#dcc777','#b96c61'],note:'SYNOP pressure reduced to mean sea level. METAR QNH is a separate variable.'},
 surface_pressure:{label:'Station pressure',unit:'hPa',min:900,max:1040,dec:1,colours:['#625a9c','#699fc0','#a3c9bc','#dcc777','#b96c61'],note:'SYNOP pressure at the station’s elevation.'},
 qnh:{label:'QNH',unit:'hPa',min:970,max:1040,dec:1,colours:['#625a9c','#699fc0','#a3c9bc','#dcc777','#b96c61'],note:'METAR altimeter setting. Kept separate from SYNOP sea-level pressure.'},
 weather:{label:'Reported weather',unit:'',categories:weatherCategories,note:'Broad categories from reported METAR / SYNOP codes. Station details retain the exact code and code table.'},
 cloud:{label:'Cloud amount · SYNOP',unit:'oktas',min:0,max:8,dec:0,colours:['#e9d7a0','#c7d4ce','#9db8c4','#6c899e','#445f7a'],note:'Reported SYNOP sky fraction in eighths. Obscured sky is not treated as 8 oktas.'},
 metar_cloud:{label:'Cloud category · METAR',unit:'',categories:[['FEW','#c8cfbd'],['SCT','#94b5bf'],['BKN','#63889e'],['OVC','#425f7c'],['CAVOK','#d3bd77'],['NSC','#d3bd77'],['NCD','#c4c6b1'],['SKC','#e4cd93'],['CLR','#e4cd93'],['Obscured','#877d96']],note:'Layer categories; CAVOK / NSC / NCD do not imply zero total cloud.'},
 visibility:{label:'Visibility',unit:'km',min:0,max:30,dec:1,colours:['#88547e','#947aa5','#89a9bb','#98c8c5','#d2dfca'],note:'Reported horizontal visibility. ≥, > and < qualifiers are retained in station details.'},
 precipitation:{label:'Precipitation accumulation',unit:'mm',min:0,max:10,dec:1,colours:blue,note:'Measured total water equivalent over the selected period, ending at its report time. Trace is preserved.'}
};
Object.assign(V,ObservationVariables);
const baseGroups={temperature:'Temperature',dewpoint:'Temperature',humidity:'Temperature',wind:'Wind',direction:'Wind',gust:'Wind',pressure_msl:'Pressure',surface_pressure:'Pressure',qnh:'Pressure',weather:'Weather & sky',cloud:'Cloud',metar_cloud:'Cloud',visibility:'Visibility',sea_temperature:'Marine',precipitation:'Precipitation'};
for(const [key,group]of Object.entries(baseGroups))V[key].group=group;
function populateVariables(){const current=variable,groups=new Map();for(const [key,v]of Object.entries(V)){const present=!data||data.stations.some(s=>key==='precipitation'?Object.keys(s.fields).some(k=>k.startsWith('precip_')):s.fields[key]);if(!present&&key!==current)continue;if(!groups.has(v.group)){const group=document.createElement('optgroup');group.label=v.group;groups.set(v.group,group);}const option=document.createElement('option');option.value=key;option.textContent=v.label;groups.get(v.group).append(option);}const order=['Temperature','Wind','Pressure','Weather & sky','Cloud','Visibility','Ground & snow','Sunshine & radiation','Marine','Precipitation','Additional observations'];$('variable').replaceChildren(...order.filter(g=>groups.has(g)).map(g=>groups.get(g)));$('variable').value=current;}
let data=null,variable='temperature',network='all',maxAge=120,period=1,selectedId=null,loading=false,selectionMarker,geographyLayer;
const map=L.map('map',{zoomControl:false,minZoom:3.5,maxZoom:13,zoomSnap:.25,preferCanvas:false});
L.control.zoom({position:'bottomright'}).addTo(map);const markers=L.layerGroup().addTo(map);map.attributionControl.addAttribution('Reports: <a href="https://www.ogimet.com/">OGIMET</a> · Geography: <a href="https://www.naturalearthdata.com/">Natural Earth</a>');
function notice(text){$('notice').textContent=text;$('notice').hidden=!text;}
function fitUK(){map.stop();map.invalidateSize();const mobile=matchMedia('(max-width:680px)').matches;map.fitBounds([[47.5,-17],[62.5,6]],{paddingTopLeft:mobile?[12,12]:[20,105],paddingBottomRight:mobile?[12,24]:[20,165],animate:false});}
const utc=t=>new Intl.DateTimeFormat('en-GB',{timeZone:'UTC',day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}).format(new Date(t*1000))+' UTC';
const timeOnly=t=>new Intl.DateTimeFormat('en-GB',{timeZone:'UTC',hour:'2-digit',minute:'2-digit'}).format(new Date(t*1000));
const age=t=>Math.max(0,Math.floor((Date.now()/1000-t)/60));
const fieldKey=key=>key==='precipitation'?`precip_${period}h`:key;
function getReading(station,key=variable,includeOld=false){const candidates=Object.values(station.fields[fieldKey(key)]||{}).filter(x=>network==='all'||x.source===network).sort((a,b)=>b.time-a.time||(a.source==='SYNOP'?-1:1));return candidates.find(x=>includeOld||age(x.time)<=maxAge)||null;}
function inNetwork(s){return Object.entries(s.reports).some(([kind,r])=>(network==='all'||network===kind)&&age(r.time)<=maxAge);}
function stations(){return (data?.stations||[]).filter(inNetwork);}
function format(reading,key=variable,short=false){if(!reading)return '—';const value=reading.value;if(typeof value==='string')return short?(reading.shortValue||value):value;if(reading.qualifier==='trace')return short?'Trace':'Trace (<0.1 mm)';let text=(reading.qualifier||'')+value.toFixed(key==='visibility'&&value<.1?2:V[key]?.dec??1);if(key==='direction'){const d=['N','NNE','NE','ENE','E','ESE','SE','SSE','S','SSW','SW','WSW','W','WNW','NW','NNW'][Math.round(value/22.5)%16];return reading.note==='Calm'?'Calm':text+'° '+d;}return text+(short?'':' '+reading.unit);}
function colour(reading){if(!reading)return '#b8c5cb';const value=reading.value,v=V[variable];if(v.text)return '#3f9cac';if(v.categories)return v.categories.find(x=>x[0]===value)?.[1]||'#78868d';if(typeof value!=='number')return '#86789b';const t=Math.max(0,Math.min(1,(value-v.min)/(v.max-v.min)))*(v.colours.length-1),i=Math.min(v.colours.length-2,Math.floor(t)),f=t-i;const a=v.colours[i].match(/\w\w/g).map(x=>parseInt(x,16)),b=v.colours[i+1].match(/\w\w/g).map(x=>parseInt(x,16));return '#'+a.map((x,j)=>Math.round(x+(b[j]-x)*f).toString(16).padStart(2,'0')).join('');}
function legend(){const v=V[variable];$('map-title').innerHTML=esc(v.label)+(variable==='precipitation'?` · ${period}h`:'')+` <span>${esc(v.unit)}</span>`;$('legend-title').textContent=v.label;$('legend-unit').textContent=v.unit;$('legend-note').textContent=v.note;$('period-wrap').hidden=variable!=='precipitation';
 if(variable==='direction'){$('legend-unit').textContent='Arrow key';$('legend-scale').innerHTML='<div class="wind-key"><span>'+WeatherWind.glyph({value:0})+'N wind blows south</span><span>'+WeatherWind.glyph({value:270})+'W wind blows east</span><span>'+WeatherWind.glyph({note:'Calm',value:0})+'Calm</span><span>'+WeatherWind.glyph({value:'VRB'})+'Variable</span></div>';}
 else if(v.text)$('legend-scale').innerHTML='<p>Reported groups and categories. Select a site for its values and original report.</p>';else if(v.categories)$('legend-scale').innerHTML='<div class="legend-categories">'+v.categories.map(([name,c])=>`<span><i style="background:${c}"></i>${esc(name)}</span>`).join('')+'</div>';
 else $('legend-scale').innerHTML=`<div class="colour-ramp" style="background:linear-gradient(90deg,${v.colours.join(',')})"></div><div class="legend-ticks">${Array.from({length:5},(_,i)=>`<span>${variable==='direction'?['N','E','S','W','N'][i]:Number((v.min+(v.max-v.min)*i/4).toFixed(1))}${i===4&&['wind','gust','precipitation','visibility'].includes(variable)?'+':''}</span>`).join('')}</div>`;

}
function render(){populateVariables();legend();markers.clearLayers();const list=stations(),values=list.map(s=>getReading(s)).filter(Boolean);let land=0,buoys=0,ships=0;
 for(const s of list){const r=getReading(s);if(s.type==='buoy')buoys++;else if(s.type==='ship')ships++;else land++;if(!r)continue;
 const marker=variable==='direction'?L.marker([s.lat,s.lon],{icon:L.divIcon({html:WeatherWind.glyph(r),className:'wind-marker',iconSize:[26,26],iconAnchor:[13,13]}),keyboard:true,bubblingMouseEvents:false}).addTo(markers):L.circleMarker([s.lat,s.lon],{radius:r?6:4,fillColor:colour(r),fillOpacity:r?.95:.35,color:s.id===selectedId?'#183f4c':'#fff',weight:s.id===selectedId?2:1,bubblingMouseEvents:false}).addTo(markers);
 const description=`${s.name} · ${s.wmo||s.icao||s.reportId}: ${r?format(r):'Not reported within age limit'}${r?' · '+timeOnly(r.time)+' UTC · '+r.source:''}`;
 marker.bindTooltip($('labels').checked?esc(format(r,variable,true)):esc(description),{permanent:$('labels').checked,direction:$('labels').checked?'right':'top',className:$('labels').checked?'point-label':'',offset:$('labels').checked?[8,0]:[0,-8]});marker.on('click',()=>selectStation(s.id));const element=marker.getElement();if(element){element.setAttribute('tabindex','0');element.setAttribute('role','button');element.setAttribute('aria-label',description);element.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();selectStation(s.id);}});}}
 $('point-count').textContent=`${values.length} readings · ${list.length} sites`;$('load-status').textContent=`${land} land · ${buoys} buoys/platforms · ${ships} ships · ${maxAge/60}h`;
 const ts=values.map(r=>r.time);$('valid-time').textContent=ts.length?`Observed ${utc(Math.min(...ts))}${Math.max(...ts)!==Math.min(...ts)?' – '+timeOnly(Math.max(...ts))+' UTC':''}`:'No readings for this variable within the selected age limit';
 if(data)$('feed-status').textContent='OGIMET fetched '+utc(data.fetchedAt)+'. '+Object.entries(data.sources).map(([kind,info])=>kind+' '+(info.ok?'available':'unavailable')).join(' · ')+'.';
 renderDetail();renderRankings();
}

function renderRankings(){const choice=$('rank-metric').value,def=WeatherRankings.definitions[choice],limit=Number($('rank-limit').value),result=WeatherRankings.rank(data?.stations,def,{network,limit});
 const notes=def.condition?'Listed by report recency; snow/ice codes do not measure snowfall depth or intensity.':choice==='rain24'?'24-hour water-equivalent precipitation, ending at each report time; not rain-only amounts.':choice==='rain1'?'One-hour water-equivalent precipitation, ending at each report time.':choice==='minimum'||choice==='maximum'?'Latest reported extreme per site. National summary periods can differ; these are not one shared calendar-day record.':choice==='snow'?'Latest measured snow depth, not snowfall amount. Non-numeric and unavailable depth codes are excluded.':choice==='gustiest'?'Reported METAR / SYNOP gusts; their averaging/reporting periods may differ.':'Latest eligible reading per land station.';
 $('rank-context').textContent='UK & Ireland land sites · '+(network==='all'?'Combined networks':network)+' · reports ≤'+def.minutes/60+'h old';$('rank-note').textContent=notes;
 $('rank-status').textContent=data?(result.eligible?result.eligible+' eligible sites · showing '+result.rows.length:choice==='snowing'?'No eligible reports of snow / ice.':'No eligible measurements for this ranking.'):'Loading station reports…';
 $('rank-list').innerHTML=result.rows.map(({station,reading},i)=>'<li><button type="button" data-rank-site="'+esc(station.id)+'"><span class="rank-number">'+(i+1)+'</span><span class="rank-place">'+esc(station.name)+'<small>'+esc(utc(reading.time))+' · '+esc(reading.source)+'</small></span><strong>'+esc(format(reading,def.map))+'</strong></button></li>').join('');
 $('rank-list').querySelectorAll('[data-rank-site]').forEach(b=>b.onclick=()=>{if(def.period){period=def.period;$('period').value=String(period);}maxAge=def.minutes;$('age').value=String(maxAge);setVariable(def.map);selectStation(b.dataset.rankSite,true);});
}
$('rank-metric').onchange=renderRankings;$('rank-limit').onchange=renderRankings;

function sourceLink(s,source){if(s.type==='buoy'||s.type==='ship'){const raw=Object.values(s.reports)[0].raw;return data.sources[raw.includes('ZZYY')?'BUOY':'SHIP'].feeds[0].url;}const id=source==='METAR'?s.icao:s.wmo;return `https://www.ogimet.com/display_${source==='METAR'?'metars':'synops'}2.php?lang=en&lugar=${encodeURIComponent(id||'')}&tipo=ALL&ord=REV&nil=SI`;}
function renderDetail(){if(!selectedId)return;const s=data?.stations.find(s=>s.id===selectedId);if(!s){clearSelection();return;}const r=getReading(s),old=getReading(s,variable,true),v=V[variable];$('clear-selection').hidden=false;let html=`<h2>${esc(s.name)}</h2><p class="station-ident">${s.type==='ship'?'Callsign '+esc(s.reportId):s.wmo?'WMO '+esc(s.wmo):''}${s.icao?' · '+esc(s.icao):''}</p><p class="detail-sub">${s.lat.toFixed(3)}°, ${s.lon.toFixed(3)}° · ${s.elevation===null?'Position reported '+utc(s.positionTime):s.elevation+' m elevation'} · ${esc(s.country||'United Kingdom')}</p><div class="selected-value ${typeof r?.value==='string'?'text-value':''}">${r?esc(format(r,variable,true)):'—'}${r&&typeof r.value==='number'&&variable!=='direction'&&r.qualifier!=='trace'?`<small>${esc(r.unit)}</small>`:''}</div><div class="weather-description">${esc(v.label)}${variable==='precipitation'?' · '+period+(period===1?' hour':' hours'):''}</div>`;
 if(r)html+=`<div class="reading-meta">${esc(r.source)}${r.derived?' · Derived value':''}<br>${utc(r.time)} · ${age(r.time)} minutes old${r.note?'<br>'+esc(r.note):''}${variable==='weather'&&r.table?'<br>Code '+esc(r.code)+' · '+esc(r.table):''}</div>`;else html+=`<p class="detail-sub stale">${old?'Last value is '+age(old.time)+' minutes old, outside the selected limit.':'No reading available for this network and age limit.'}</p>`;
 html+='<dl class="metric-list">'+Object.entries(V).filter(([key])=>getReading(s,key)).map(([key,def])=>{const read=getReading(s,key);return `<div class="metric-row ${key===variable?'active':''} ${read?'':'missing'}"><dt><button type="button" data-variable="${key}">${def.label}${key==='precipitation'?' · '+period+'h':''}</button></dt><dd>${esc(format(read,key))}${read?`<small>${timeOnly(read.time)} UTC · ${read.source}${read.derived?' · derived':''}</small>`:''}</dd></div>`;}).join('')+'</dl>';
 if(r)html+=`<details class="raw-report" open><summary>Raw report for this reading</summary><pre>${esc(r.raw)}</pre><a href="${sourceLink(s,r.source)}" target="_blank" rel="noreferrer">View ${s.type==='buoy'||s.type==='ship'?'marine feed':'station reports'} on OGIMET</a></details>`;
 for(const [kind,report]of Object.entries(s.reports))html+=`<details class="raw-report"><summary>Latest ${kind} · ${timeOnly(report.time)} UTC</summary><pre>${esc(report.raw)}</pre></details>`;
 html+='<p class="detail-sub">Each reading keeps its own timestamp and source. An unreported value is not a measured zero.</p>';$('detail-content').innerHTML=html;$('detail-content').querySelectorAll('[data-variable]').forEach(b=>b.onclick=()=>setVariable(b.dataset.variable));
}
function selectStation(id,pan=false){const s=data?.stations.find(s=>s.id===id);if(!s)throw Error('Station not found in retrieved reports');selectedId=id;if(selectionMarker)selectionMarker.remove();selectionMarker=L.circleMarker([s.lat,s.lon],{radius:12,color:'#173f4c',fill:false,weight:2,interactive:false}).addTo(map);if(pan)map.setView([s.lat,s.lon],8,{animate:false});renderDetail();return s;}
function clearSelection(){selectedId=null;if(selectionMarker)selectionMarker.remove();$('clear-selection').hidden=true;$('detail-content').innerHTML='<div class="empty-pin" aria-hidden="true">⌖</div><h2>Read the observation</h2><p>Select a station to see its readings, observation times and original METAR or SYNOP report.</p>';}
function setVariable(key){if(!Object.hasOwn(V,key))throw Error('Unsupported observation');variable=key;if(V[key].summary){maxAge=1440;$('age').value='1440';}$('variable').value=key;render();}
function search(){const q=$('search').value.trim().toLowerCase();$('search-results').replaceChildren();if(!q)return;const matches=(data?.stations||[]).filter(s=>[s.name,s.wmo,s.icao].filter(Boolean).some(x=>x.toLowerCase().includes(q))).slice(0,12);if(!matches.length){$('search-results').textContent='No reporting station matches. Try a station name, WMO or ICAO code.';return;}for(const s of matches){const b=document.createElement('button');b.type='button';b.textContent=s.name;const t=document.createElement('small');t.textContent=[s.wmo,s.icao,Object.keys(s.reports).join(' + ')].filter(Boolean).join(' · ');b.append(t);b.onclick=()=>{$('search').value=s.name;$('search-results').replaceChildren();selectStation(s.id,true);};$('search-results').append(b);}}
async function refresh(){if(loading)return;loading=true;$('refresh').disabled=true;$('load-status').textContent='Retrieving station reports…';try{const r=await fetch('/api/observations',{cache:'no-store',signal:AbortSignal.timeout(85000)});const next=await r.json();if(!r.ok||!next.success)throw Error(next.error||next.warnings?.join(' ')||'OGIMET reports are temporarily unavailable. Try again shortly.');data=next;render();notice(next.warnings.join(' '));}catch(e){notice((data?'Could not refresh; retained readings keep their original observation times. ':'')+e.message);if(data)render();else{$('load-status').textContent='Reports unavailable · use Refresh reports';$('feed-status').textContent='Observation feeds could not load. Use Refresh reports to retry.';}}finally{loading=false;$('refresh').disabled=false;}}
$('variable').addEventListener('change',e=>setVariable(e.target.value));$('period').onchange=e=>{period=Number(e.target.value);render();};$('age').onchange=e=>{maxAge=Number(e.target.value);render();};$('labels').onchange=render;document.querySelectorAll('[data-network]').forEach(b=>b.onclick=()=>{network=b.dataset.network;document.querySelectorAll('[data-network]').forEach(x=>x.setAttribute('aria-pressed',String(x.dataset.network===network)));render();});$('refresh').onclick=refresh;$('fit-uk').onclick=fitUK;$('clear-selection').onclick=clearSelection;$('search-form').onsubmit=e=>{e.preventDefault();search();};$('search').oninput=search;
map.on('click',e=>{const list=stations().filter(s=>getReading(s));if(!list.length)return;const sorted=list.map(s=>({s,km:Math.hypot((s.lat-e.latlng.lat)*111.32,(s.lon-e.latlng.lng)*111.32*Math.cos(e.latlng.lat*Math.PI/180))})).sort((a,b)=>a.km-b.km);if(sorted[0].km>100){notice('No reporting station within 100 km of that point. Choose a station marker.');return;}selectStation(sorted[0].s.id);notice(`Selected ${sorted[0].s.name}, the nearest reporting station (${Math.round(sorted[0].km)} km from your click).`);});
setInterval(()=>{if(!document.hidden)refresh();},600000);setInterval(()=>{if(data&&!document.hidden)render();},60000);
function registerTools(){if(!document.modelContext?.registerTool)return;const controller=new AbortController();const tools=[{name:'set_observation_map',description:'Set the observation variable, reporting network, and maximum age on the visible UK, Ireland and marine observation map.',inputSchema:{type:'object',properties:{variable:{type:'string',enum:Object.keys(V)},network:{type:'string',enum:['all','SYNOP','METAR','BUOY','SHIP']},max_age_minutes:{type:'integer',enum:[60,120,360,1440]}},required:['variable'],additionalProperties:false},annotations:{readOnlyHint:false},async execute(input){if(!input||!Object.hasOwn(V,input.variable)||input.network!==undefined&&!['all','SYNOP','METAR','BUOY','SHIP'].includes(input.network)||input.max_age_minutes!==undefined&&![60,120,360,1440].includes(input.max_age_minutes))throw Error('Invalid observation map selection');variable=input.variable;network=input.network??network;maxAge=input.max_age_minutes??(V[variable].summary?1440:maxAge);$('variable').value=variable;$('age').value=String(maxAge);document.querySelectorAll('[data-network]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.network===network)));render();return {variable,network,max_age_minutes:maxAge,stations:stations().length,readings:stations().filter(s=>getReading(s)).length};}},{name:'inspect_reporting_station',description:'Select a reporting site by its WMO, ICAO or marine callsign identifier and show its observed reading and raw report.',inputSchema:{type:'object',properties:{station_id:{type:'string'}},required:['station_id'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},async execute(input){if(!input||typeof input.station_id!=='string')throw Error('Station identifier required');const id=input.station_id.toUpperCase(),s=data?.stations.find(s=>s.id===id||s.wmo===id||s.icao===id||s.reportId===id||s.id==='marine:'+id);if(!s)throw Error('Reporting station not found');selectStation(s.id,true);return {station:s.name,wmo:s.wmo,icao:s.icao,reading:getReading(s)};}}];for(const tool of tools){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:controller.signal})).catch(()=>{});}catch{}}window.addEventListener('pagehide',()=>controller.abort(),{once:true});}
function geographyStyle(f){const focus=f.properties.uk||f.properties.name==='Ireland',dark=$('dark-map').checked;return {color:dark?(focus?'#607f8d':'#354c5a'):(focus?'#9bb4be':'#b9cbd3'),weight:focus?1.25:.8,fillColor:dark?(focus?'#263f4c':'#1e333f'):(focus?'#f7faf9':'#eaf0f1'),fillOpacity:1};}
function applyMapTheme(){document.querySelector('.map-shell').classList.toggle('dark-map',$('dark-map').checked);geographyLayer?.setStyle(geographyStyle);try{localStorage.setItem('weather-map-theme',$('dark-map').checked?'dark':'light');}catch{}}
try{$('dark-map').checked=localStorage.getItem('weather-map-theme')==='dark';}catch{}
$('dark-map').onchange=applyMapTheme;applyMapTheme();
const phoneLayout=matchMedia('(max-width:680px)');function syncLegendLayout(){document.querySelector('.legend-details').open=!phoneLayout.matches;}phoneLayout.addEventListener('change',syncLegendLayout);syncLegendLayout();
async function init(){try{const r=await fetch('geography.json');if(!r.ok)throw Error();geographyLayer=L.geoJSON(await r.json(),{pane:'tilePane',style:geographyStyle,interactive:false}).addTo(map);}catch{notice('The base map could not load. Station observations are still available.');}fitUK();legend();await refresh();registerTools();}init();
